DROP TABLE IF EXISTS `books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `books` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT (uuid()),
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `isbn` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `average_rating` float NOT NULL DEFAULT '0',
  `cover_image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ol_cover_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `num_pages` int NOT NULL,
  `published_year` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_added_by_system` tinyint(1) NOT NULL DEFAULT '0',
  `book_status` enum('approved','waiting-for-approval') COLLATE utf8mb4_unicode_ci NOT NULL,
  `added_by` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `books_added_by_foreign` (`added_by`),
  FULLTEXT KEY `books_fulltext_search` (`title`,`description`),
  CONSTRAINT `books_added_by_foreign` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
